483	  <!-- API call example -->
484	  <div class="card card-green">
485	    <span class="card-tag tag-green">Python Implementation</span>
486	    <h3>API Integration Code (TRL-Free, Pure Mistral SDK)</h3>
487	    <p>Every Mistral call is a single API request. Total cost ≈ $0.02 per reasoning cycle. At 1 call/30s, that's **≈$2.90/day**.</p>
488	<pre><code><span class="kw">from</span> mistralai <span class="kw">import</span> Mistral
489	<span class="kw">import</span> json, os
490	
491	client = Mistral(api_key=[REDACTED] class="str">"MISTRAL_API_KEY"</span>])
492	
493	<span class="kw">def</span> <span class="fn">flowsync_tick</span>(cityflow_state):
494	    <span class="cm"># 1. Summarize cityflow state → prompt</span>
495	    state_summary = {
496	        <span class="str">"intersection_queues"</span>: cityflow_state.get_queues(),
497	        <span class="str">"avg_speeds"</span>: cityflow_state.get_speeds(),
498	        <span class="str">"active_incidents"</span>: cityflow_state.get_incidents(),
499	        <span class="str">"weather"</span>: cityflow_state.get_weather(),
500	    }
501	
502	    <span class="cm"># 2. Build messages</span>
503	    messages = [
504	        {<span class="str">"role"</span>: <span class="str">"system"</span>, <span class="str">"content"</span>: SYSTEM_PROMPT},
505	        {<span class="str">"role"</span>: <span class="str">"user"</span>, <span class="str">"content"</span>: json.dumps(state_summary)}
506	    ]
507	
508	    <span class="cm"># 3. Call Mistral with tools</span>
509	    response = client.chat.complete(
510	        model=<span class="str">"mistral-large-latest"</span>,
511	        messages=messages,
512	        tools=FS_TOOLS,       <span class="cm"># adjust_signal, predict, etc.</span>
513	        tool_choice=<span class="str">"auto"</span>,
514	        temperature=<span class="num">0.1</span>,    <span class="cm"># Low temp = deterministic safety</span>
515	    )
516	
517	    <span class="cm"># 4. Execute tool calls</span>
518	    <span class="kw">for</span> tc <span class="kw">in</span> response.choices[<span class="num">0</span>].message.tool_calls:
519	        result = execute_tool(tc.function.name, tc.function.arguments)
520	        logging.info(<span class="str">f"Tool {tc.function.name}: {result}"</span>)
521	
522	    <span class="cm"># 5. CityFlow applies changes (MCP call to SUMO)</span>
523	    cityflow_state.apply_changes()
524	
525	    <span class="cm"># 6. Push to dashboard (30 FPS WebSocket)</span>
526	    ws_manager.broadcast(cityflow_state.snapshot())</code></pre>
