571	  <!-- Safety -->
572	  <div class="card card-red">
573	    <span class="card-tag tag-red">Safety Filter (Critical for Judges)</span>
574	    <h3>Deterministic Conflict Filter</h3>
575	    <p>Even with API-only, a deterministic safety layer blocks any dangerous signal combination. This is what judges care about most.</p>
576	<pre><code><span class="kw">def</span> <span class="fn">conflict_filter</span>(intersection_id, proposed_green, phase_name):
577	    <span class="cm"># Load conflict matrix from signal_timing_plans (open data!)</span>
578	    matrix = load_conflict_matrix(intersection_id)  <span class="cm"># From RTA dataset</span>
579	    current_state = cityflow.get_phase(intersection_id)
580	
581	    <span class="cm"># Hard rule: proposed green must be within TOD bounds</span>
582	    tod_green = get_tod_green(intersection_id, current_time)
583	    min_g, max_g = tod_green * <span class="num">.7</span>, tod_green * <span class="num">1.3</span>
584	    <span class="kw">if</span> <span class="kw">not</span> (min_g <= proposed_green <= max_g):
585	        reject(<span class="str">"outside TOD bounds"</span>)
586	
587	    <span class="cm"># Hard rule: no conflicting greens</span>
588	    conflicting_phases = matrix[phase_name]
589	    <span class="kw">for</span> cp <span class="kw">in</span> conflicting_phases:
590	        <span class="kw">if</span> current_state[cp].green > <span class="num">0</span>:
591	            reject(<span class="str">f"conflict with {cp}"</span>)
592	
593	    <span class="cm"># If passes → apply</span>
594	    cityflow.apply_signal(intersection_id, proposed_green, phase_name)
595	    <span class="kw">return</span> <span class="str">"PASS"</span></code></pre>
