702	
703	train_ds = dataset.map(format_chatml)
704	
705	trainer = SFTTrainer(
706	    model=<span class="str">"mistralai/Mistral-7B-Instruct-v0.3"</span>,
707	    train_dataset=train_ds,
708	    dataset_text_field=<span class="str">"messages"</span>,
