723	  </div>
724	
725	  <!-- GRPO -->
726	  <div class="card card-purple">
727	    <span class="card-tag tag-purple">Phase 2 · GRPO — Auction Reward Optimization</span>
728	    <h3>GRPO with CityFlow Simulator as Reward Function</h3>
729	<pre><code><span class="kw">from</span> trl <span class="kw">import</span> GRPOTrainer
730	
731	<span class="kw">def</span> <span class="fn">vcg_auction_reward</span>(prompts, completions, **kwargs):
732	    <span class="cm">"""
733	    Reward = weighted sum of (from CityFlow simulation):
734	      - congestion_reduction (primary) — measured from signal_performance_hourly
735	      - revenue_generated (secondary) — measured from auction clearing prices
736	      - fairness_across_fleets (tertiary) — no single fleet dominates slots
737	    """</span>
738	    rewards = []
739	    <span class="kw">for</span> completion <span class="kw">in</span> completions:
740	        <span class="cm"># 1. Parse completion → action dict</span>
741	        action = parse_json_safely(completion)
742	
743	        <span class="cm"># 2. Validate against signal_timing_plans bounds</span>
744	        <span class="kw">if</span> <span class="kw">not</span> within_tod_bounds(action, plans):
745	            rewards.append(-<span class="num">1.0</span>)   <span class="cm"># Hard penalty</span>
746	            <span class="kw">continue</span>
747	
748	        <span class="cm"># 3. Run CityFlow sim with proposed action</span>
749	        result = cityflow_sim.step(action, duration_min=<span class="num">30</span>)
750	
751	        <span class="cm"># 4. Compute reward from result metrics</span>
752	        delay_delta = result.avg_delay_before - result.avg_delay_after
753	        revenue    = result.total_auction_revenue
754	        fairness   = gini_coefficient(result.fleet_utilization)
755	
756	        score = <span class="num">0.6</span> * normalize(delay_delta) + <span class="num">0.3</span> * normalize(revenue) - <span class="num">0.1</span> * fairness
757	        rewards.append(score)
758	
759	    <span class="kw">return</span> rewards
760	
761	grpo_trainer = GRPOTrainer(
762	    model=<span class="str">"mistralai/Mistral-7B-v0.3"</span>,
763	    reward_funcs=vcg_auction_reward,
764	    train_dataset=auction_scenarios_ds,
765	)
766	grpo_trainer.train()
767	grpo_trainer.push_to_hub(<span class="str">"your-org/mistral-flowsync-grpo-v1"</span>)</code></pre>
768	  </div>
769	
