const API_BASE = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8000";

export interface Location {
  location_id: string;
  name: string;
  road: string;
  area: string;
  direction: string;
  latitude: number;
  longitude: number;
  num_lanes: number;
  capacity_vph: number;
  free_flow_speed: number;
  volume_vph: number;
  demand_vph: number;
  avg_speed_kph: number;
  vc_ratio: number;
  occupancy_pct: number;
  level_of_service: string;
  congestion: string;
  color: string;
}

export interface Phase {
  phase_id: string;
  movement: string;
  green_s: number;
  yellow_s: number;
  all_red_s: number;
  min_green_s: number;
  max_green_s: number;
  adjusted?: boolean;
  delta?: number;
}

export interface Junction {
  junction_id: string;
  name: string;
  area: string;
  latitude: number;
  longitude: number;
  num_approaches: number;
  control_type: string;
  active_program: string;
  cycle_length_s: number;
  degree_of_saturation: number;
  avg_delay_s_per_veh: number;
  avg_queue_veh: number;
  throughput_vph: number;
  phase_failures: number;
  adaptive_active: boolean;
  phases: Phase[];
}

export interface Weather {
  temp_c: number;
  humidity_pct: number;
  wind_kph: number;
  visibility_km: number;
  precip_mm: number;
  condition: string;
}

export interface Incident {
  incident_id: string;
  type: string;
  severity: string;
  road: string;
  area: string;
  latitude: number;
  longitude: number;
  lanes_blocked: number;
  duration_min: number;
}

export interface Metrics {
  total_volume_vph: number;
  avg_speed_kph: number;
  avg_vc_ratio: number;
  critical_locations: number;
  heavy_locations: number;
  total_delay_s: number;
  total_queue_veh: number;
  phase_failures: number;
  active_incidents: number;
}

export interface Frame {
  timestamp: string;
