"use client";

import type { Metrics } from "@/lib/api";

interface MetricsPanelProps {
  baseline: Metrics;
  optimized?: Metrics;
  improvements?: {
    delay_reduction_pct: number;
    throughput_increase_pct: number;
    critical_resolved: number;
    queue_reduction_pct: number;
    speed_increase_pct: number;
    vehicles_rerouted: number;
    time_saved_min: number;
    signal_adjustments: number;
  };
}

function MetricCard({
  label,
  value,
  unit,
  delta,
  color = "blue",
}: {
  label: string;
  value: string | number;
  unit?: string;
  delta?: number;
  color?: "blue" | "green" | "red" | "orange" | "purple";
}) {
  const colorMap = {
    blue: "text-blue-400",
    green: "text-emerald-400",
    red: "text-red-400",
    orange: "text-orange-400",
    purple: "text-purple-400",
  };

  return (
    <div className="bg-[#1a2236] border border-[#2a3550] rounded-xl p-4 flex flex-col gap-1">
      <span className="text-[#94a3b8] text-xs font-medium uppercase tracking-wider">
        {label}
      </span>
      <div className="flex items-baseline gap-1">
        <span className={`text-2xl font-bold ${colorMap[color]}`}>{value}</span>
        {unit && <span className="text-[#94a3b8] text-xs">{unit}</span>}
      </div>
      {delta !== undefined && (
        <span
          className={`text-xs font-medium ${
            delta > 0 ? "text-emerald-400" : delta < 0 ? "text-red-400" : "text-[#94a3b8]"
          }`}
        >
          {delta > 0 ? "↓" : delta < 0 ? "↑" : "—"} {Math.abs(delta)}%
        </span>
      )}
    </div>
  );
}

export default function MetricsPanel({
  baseline,
  optimized,
  improvements,
}: MetricsPanelProps) {
  return (
    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
      <MetricCard
        label="Avg Speed"
        value={optimized?.avg_speed_kph ?? baseline.avg_speed_kph}
        unit="km/h"
        delta={improvements?.speed_increase_pct}
        color="blue"
      />
      <MetricCard
        label="Total Delay"
        value={optimized?.total_delay_s ?? baseline.total_delay_s}
        unit="s"
        delta={improvements ? -improvements.delay_reduction_pct : undefined}
        color="red"
      />
      <MetricCard
        label="Queue Length"
        value={optimized?.total_queue_veh ?? baseline.total_queue_veh}
        unit="veh"
        delta={improvements ? -improvements.queue_reduction_pct : undefined}
        color="orange"
      />
      <MetricCard
        label="Critical Points"
        value={optimized?.critical_locations ?? baseline.critical_locations}
        delta={
          improvements
            ? -(improvements.critical_resolved * 10)
            : undefined
        }
        color="red"
      />
      <MetricCard
        label="Throughput"
        value={optimized?.total_volume_vph ?? baseline.total_volume_vph}
        unit="vph"
        delta={improvements?.throughput_increase_pct}
        color="green"
      />
      <MetricCard
        label="Phase Failures"
        value={optimized?.phase_failures ?? baseline.phase_failures}
        color="orange"
      />
      <MetricCard
        label="Time Saved"
        value={improvements?.time_saved_min ?? 0}
        unit="min"
        color="purple"
      />
      <MetricCard
        label="Vehicles Rerouted"
        value={improvements?.vehicles_rerouted ?? 0}
        color="blue"
      />
    </div>
  );
}

"use client";

import { useEffect, useRef } from "react";
import type { SignalAdjustment, ReroutingRecommendation } from "@/lib/api";

interface ReasoningPanelProps {
  reasoning: string;
  adjustments: SignalAdjustment[];
  rerouting: ReroutingRecommendation[];
  source: string;
  model: string;
  optimized: boolean;
}

export default function ReasoningPanel({
  reasoning,
  adjustments,
  rerouting,
  source,
  model,
  optimized,
}: ReasoningPanelProps) {
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [reasoning, adjustments, rerouting]);

  if (!optimized) {
    return (
      <div className="bg-[#161d2e] border border-[#2a3550] rounded-xl p-4 h-full flex flex-col">
        <div className="flex items-center gap-2 mb-3">
          <div className="w-2 h-2 rounded-full bg-gray-500" />
          <h3 className="text-sm font-semibold text-[#94a3b8]">
            Mistral AI Reasoning
          </h3>
        </div>
        <div className="flex-1 flex items-center justify-center">
          <p className="text-[#64748b] text-sm text-center">
            Switch to FlowSync view to see Mistral AI optimization reasoning
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-[#161d2e] border border-[#2a3550] rounded-xl p-4 h-full flex flex-col">
      <div className="flex items-center justify-between mb-3">
        <div className="flex items-center gap-2">
          <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse" />
          <h3 className="text-sm font-semibold text-white">
            Mistral AI Reasoning
          </h3>
        </div>
        <span className="text-xs px-2 py-0.5 rounded-full bg-purple-500/20 text-purple-300 border border-purple-500/30">
          {source === "mistral_ai" ? "Mistral API" : "Heuristic"}
        </span>
      </div>

      <div ref={scrollRef} className="flex-1 overflow-y-auto space-y-3 pr-1">
        {/* Main reasoning */}
        {reasoning && (
          <div className="bg-[#1a2236] rounded-lg p-3 border border-[#2a3550]">
            <p className="text-sm text-[#e2e8f0] leading-relaxed">{reasoning}</p>
          </div>
        )}

        {/* Signal adjustments */}
        {adjustments.length > 0 && (
          <div className="space-y-2">
            <h4 className="text-xs font-semibold text-orange-400 uppercase tracking-wider">
              Signal Adjustments
            </h4>
            {adjustments.map((adj, i) => (
              <div
                key={i}
                className="bg-[#1a2236] rounded-lg p-3 border border-[#2a3550] flex items-start gap-2"
              >
                <div className="w-6 h-6 rounded-full bg-orange-500/20 flex items-center justify-center flex-shrink-0 mt-0.5">
                  <span className="text-xs">🚦</span>
                </div>
                <div>
                  <p className="text-sm text-[#e2e8f0]">
                    <span className="font-mono text-orange-300">
                      {adj.junction_id}
                    </span>{" "}
                    — Phase {adj.phase_id}
                  </p>
                  <p className="text-xs text-[#94a3b8] mt-0.5">
                    {adj.reason}
                  </p>
                  <p className="text-xs mt-1">
                    <span
                      className={
                        adj.green_delta_s > 0
                          ? "text-emerald-400"
                          : "text-red-400"
                      }
                    >
                      {adj.green_delta_s > 0 ? "+" : ""}
                      {adj.green_delta_s}s green
                    </span>
                  </p>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Rerouting */}
        {rerouting.length > 0 && (
          <div className="space-y-2">
            <h4 className="text-xs font-semibold text-blue-400 uppercase tracking-wider">
              Rerouting
            </h4>
            {rerouting.map((r, i) => (
              <div
                key={i}
                className="bg-[#1a2236] rounded-lg p-3 border border-[#2a3550] flex items-start gap-2"
              >
                <div className="w-6 h-6 rounded-full bg-blue-500/20 flex items-center justify-center flex-shrink-0 mt-0.5">
                  <span className="text-xs">🔄</span>
                </div>
                <div>
                  <p className="text-sm text-[#e2e8f0]">
                    {r.from_location} →{" "}
                    <span className="text-blue-300">{r.to_alternative}</span>
                  </p>
                  <p className="text-xs text-[#94a3b8] mt-0.5">{r.reason}</p>
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Model info */}
        <div className="pt-2 border-t border-[#2a3550]">
          <p className="text-xs text-[#64748b]">
            Model: <span className="text-[#94a3b8]">{model}</span>
          </p>
        </div>
      </div>
    </div>
  );
}

